<template><aside class="builder-panel inspector-panel"><header class="builder-panel__heading"><strong>✣ Widget Settings</strong><small>{{ widget?.name||'No selection' }}</small></header><div class="inspector-tabs"><button :class="{active:tab==='settings'}" @click="tab='settings'">Settings</button><button :class="{active:tab==='suggestions'}" @click="tab='suggestions'">Suggestions <span>{{ suggestions.length }}</span></button></div><template v-if="tab==='settings'"><div v-if="widget&&definition" class="inspector-fields"><label>Display name<input :value="widget.name" @change="patch({name:$event.target.value})"></label><label>Theme<select :value="widget.themeId||themeId" @change="patch({themeId:$event.target.value})"><option v-for="t in themes" :key="t.id" :value="t.id">{{ t.name }}</option></select></label><div class="frame-fields"><label v-for="key in ['x','y','width','height']" :key="key">{{ key.toUpperCase() }}<input type="number" min="0" :value="widget.frame[key]" @change="frame(key,$event.target.value)"></label></div><label v-for="field in definition.settings" :key="field.key"><span>{{ field.label }}</span><input v-if="field.type==='checkbox'" type="checkbox" :checked="widget.settings[field.key]" @change="setting(field,$event.target.checked)"><textarea v-else-if="field.type==='textarea'" :value="widget.settings[field.key]" @change="setting(field,$event.target.value)"></textarea><select v-else-if="field.type==='select'" :value="widget.settings[field.key]" @change="setting(field,$event.target.value)"><option v-for="o in field.options" :key="o">{{ o }}</option></select><input v-else :type="field.type" :min="field.min" :max="field.max" :step="field.step" :value="widget.settings[field.key]" @change="setting(field,$event.target.value)"></label><label>Animation<select :value="widget.animations.entrance" @change="patch({animations:{...widget.animations,entrance:$event.target.value}})"><option>slide</option><option>fade</option><option>pop</option><option>none</option></select></label><label>Animation duration<input type="number" :value="widget.animations.durationMs" min="100" max="30000" @change="patch({animations:{...widget.animations,durationMs:Number($event.target.value)}})"></label></div><div v-else class="empty-inspector">Select a widget from the library, canvas or layers.</div></template><div v-else class="suggestion-list"><article v-if="!suggestions.length"><b>Layout looks balanced</b><p>No deterministic suggestions for this scene.</p></article><article v-for="item in suggestions" :key="item.id" :class="item.severity"><b>{{ item.title }}</b><p>{{ item.message }}</p><button v-if="item.action" @click="$emit('suggestion',item)">{{ item.actionLabel }}</button></article></div></aside></template>
<script setup>import{computed,ref}from'vue';import{widgetRegistry}from'../../overlays/widgetRegistry.js';const props=defineProps({widget:Object,suggestions:Array,themes:Array,themeId:String});const emit=defineEmits(['change','suggestion']);const tab=ref('settings');const definition=computed(()=>props.widget?widgetRegistry[props.widget.type]:null);function patch(next){emit('change',{...props.widget,...next,updatedAt:'2026-08-13T15:00:00.000Z'})}function frame(key,value){patch({frame:{...props.widget.frame,[key]:Math.max(0,Number(value))}})}function setting(field,value){patch({settings:{...props.widget.settings,[field.key]:['number','range'].includes(field.type)?Number(value):value}})}</script>
